import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
import { useSearchParam, asFlag } from '../../url/useSearchParam';

// "Show archived" — a self-contained control that owns the `showArchived` URL key. Archived projects
// are hidden by default; the projects list reads the same key and, when it is on, reveals archived
// rows too. The two share only the key, no import. The flag lives in the URL so the revealed view
// outlives the click and is shareable.
function ShowArchived() {
  const [showArchived, setShowArchived] = useSearchParam('showArchived', asFlag);
  return (
    <button
      type="button"
      data-testid="projects-show-archived"
      aria-pressed={showArchived}
      onClick={() => setShowArchived(showArchived ? undefined : true)}
    >
      {showArchived ? 'Hide archived' : 'Show archived'}
    </button>
  );
}

export const contribution = ProjectsToolbar.fill({ order: 10, Component: ShowArchived });
===taskFilter.slot===
import { ProjectTasksToolbar } from '../../slots/defs/projectTasksToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';

// "Show just the open ones, or just the finished ones" — a self-contained control that owns the
// `taskFilter` URL key. The task list reads the same key and keeps only matching rows; the two share
// only the key, no import. Choosing a state commits it to the URL (so the narrowed view outlives the
// click and is shareable); the empty option clears the key and shows every task again.
const STATES = ['OPEN', 'DONE'] as const;

function TaskFilter() {
  const [filter, setFilter] = useSearchParam('taskFilter', asString);
  return (
    <select
      data-testid="task-filter"
      value={filter}
      onChange={(e) => setFilter(e.target.value)}
    >
      <option value="">All tasks</option>
      {STATES.map((state) => (
        <option key={state} value={state}>
          {state}
        </option>
      ))}
    </select>
  );
}

export const contribution = ProjectTasksToolbar.fill({ order: 10, Component: TaskFilter });
===projectsToolbar def===
import { defineSlot } from '../Slot';

/**
 * Controls that act on the projects list — a filter, a toggle, a sort. Rendered above the projects
 * table by the projects feature; each control is its own `*.slot.tsx` file and owns a URL search
 * param, so the list never lists its controls. No context: it spans every project.
 */
export const ProjectsToolbar = defineSlot('projects.toolbar');
===projects.index===
import { createFileRoute } from '@tanstack/react-router';
import { ProjectForm } from '../features/projects/ProjectForm';
import { ProjectList } from '../features/projects/ProjectList';

// The Projects page: one new file under routes/. The route table is generated from this directory.
export const Route = createFileRoute('/projects/')({
  component: ProjectsPage,
});

function ProjectsPage() {
  return (
    <section data-testid="projects-page">
      <h1>Projects</h1>
      <ProjectForm />
      <ProjectList />
    </section>
  );
}

